import React, { useState } from "react";

function App() {
  const [formData, setFormData] = useState({
    hs_avg: "",
    first_term_gpa: "",
    math_score: "",
    english_grade: ""
  });

  const [result, setResult] = useState(null);

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async () => {
    // 🔥 FAKE DATA for now (backend not ready yet)
    const fakeResult = {
      completion: "Yes",
      persistence: "Yes",
      gpa: 3.4,
      performance: "High"
    };

    setResult(fakeResult);
  };

  return (
    <div style={{ padding: "30px", fontFamily: "Arial" }}>
      <h1>🎓 Student Success Prediction</h1>

      <h2>📥 Input Student Data</h2>

      <input name="hs_avg" placeholder="High School Average" onChange={handleChange} /><br /><br />
      <input name="first_term_gpa" placeholder="First Term GPA" onChange={handleChange} /><br /><br />
      <input name="math_score" placeholder="Math Score" onChange={handleChange} /><br /><br />
      <input name="english_grade" placeholder="English Grade" onChange={handleChange} /><br /><br />

      <button onClick={handleSubmit}>Predict</button>

      {result && (
        <div style={{ marginTop: "30px" }}>
          <h2>📊 Results</h2>
          <p>✅ Completion: {result.completion}</p>
          <p>📘 Persistence: {result.persistence}</p>
          <p>📈 Predicted GPA: {result.gpa}</p>
          <p>🏆 Performance: {result.performance}</p>
        </div>
      )}
    </div>
  );
}

export default App;













